        "status": "current",
        "language": "it",
        "text": "Il Codice il più delle volte non definisce i riti, che sono da osservarsi nel celebrare le azioni liturgiche; di conseguenza le leggi liturgiche finora vigenti mantengono il loro vigore, a meno che qualcuna di esse non sia contraria ai canoni del Codice.",
